def reverse_alternating_blocks(s,k):
    chars=list(s)
    for start in range(0,len(chars),2*k):
        left=start;right=min(start+k,len(chars))-1
        while left<right:
            chars[left],chars[right]=chars[right],chars[left];left+=1;right-=1
    return ''.join(chars)

